  const wy2 = Math.cos(sy*0.025-sx*0.01-t*0.35)*6 + Math.sin(sx*0.028+t*0.45)*5;
  const dx = sx + wx2, dy = sy + wy2;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08, 2.0, 1.0],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1, 1.7, 0.9],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06, 2.3, 1.1],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.12, 1.5, 0.8],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.07, 2.6, 1.2],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.09, 1.9, 0.95],
    [80+Math.sin(t*0.45+3)*60, 40+Math.cos(t*0.65+2)*40, 0.14, 2.1, 0.85],
    [400+Math.cos(t*0.55+1)*70, 200+Math.sin(t*0.75+4)*50, 0.11, 1.8, 1.05],
    [200+Math.sin(t*0.7+6)*90, 220+Math.cos(t*0.3+3)*30, 0.09, 2.4, 0.9],
    [300+Math.cos(t*0.42+2)*80, 100+Math.sin(t*0.58+5)*60, 0.13, 2.0, 1.1]
  ];
  let aS = 0, iS = 0, hS = 0;
  for (const [sX, sY, f, sp, w] of src) {
    const d = Math.sqrt((dx-sX)**2 + (dy-sY)**2);
    aS += Math.sin(d*f - t*sp) * w;
    iS += Math.sin(d*f*0.7 + t*sp*0.6 + 1.5) * w;
    hS += Math.sin(d*f*1.3 - t*sp*0.8 + 2.0) * w;
  }
  const act = aS/10, inh = iS/10, harm = hS/10;
  const bg1 = (Math.sin(dx*0.04+dy*0.025+t*0.8) + Math.sin(dx*0.03-dy*0.04+t*1.1))/2;
  const bg2 = Math.sin((dx+dy)*0.12+t*2.5)*0.2 + Math.sin((dx-dy)*0.1-t*2)*0.2;
  const bg3 = Math.sin(dx*0.08+t*0.6)*Math.cos(dy*0.06-t*0.4)*0.15;
  const bg = bg1 + bg2 + bg3;
  const dist = Math.sqrt((dx-cx)**2 + (dy-cy)**2), ang = Math.atan2(dy-cy, dx-cx);
  const spiral1 = (Math.sin(dist*0.05-ang*3-t*1.5) + Math.sin(dist*0.04+ang*4-t*1.2))*0.4;
  const spiral2 = Math.sin(dist*0.03-ang*5+t*0.8)*Math.cos(dist*0.025+ang*2-t*0.6)*0.3;
  const spiral = spiral1 + spiral2;
  const r1 = Math.tanh((act - inh*0.7 + bg*0.3 + spiral)*2.2);
  const r2 = Math.tanh((harm - act*0.5 - inh*0.3 + spiral*0.5)*1.8);
  const r3 = Math.tanh((r1*0.6 + r2*0.4 + bg*0.2)*2.0);
  const cell = Math.tanh((Math.sin(dx*0.15)*Math.sin(dy*0.15) + Math.sin((dx+dy)*0.1+t)*0.5)*1.5)*0.3;
  const edge = Math.abs(r1 - r2) * 1.5;
  const blend = r3*0.6 + cell*0.2 + Math.tanh(edge)*0.2;
  const v = blend*0.5+0.5;
  const vig = 1.0 - Math.sqrt((x-cx)**2+(y-cy)**2)/350*0.3;
  const pal = [[6,12,52],[12,45,95],[18,95,125],[25,155,145],[120,185,140],[210,195,80],[225,145,65],[195,75,55],[140,35,55],[75,18,55],[6,12,52]];
  const idx = v*(pal.length-1), i = Math.min(idx|0, pal.length-2), f = idx-i;
  const lum = (0.8+Math.sin(r1*Math.PI)*0.2) * vig;
  const eb = Math.tanh(edge*2.0)*0.15;
  return [
    Math.min(255, ((pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum + eb*255)|0),
    Math.min(255, ((pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum + eb*180)|0),
